  "causes": [
    {
      "hypothesis_id": "H3",
      "type": "mix_shift",
      "summary": "Product mix shifted toward higher-frequency categories on 24 Nov 2017.",
      "confidence": 0.75,
      "observation_ids": ["obs-3"],
      "statements": [
        {
          "text": "On 24 Nov 2017 the share of orders in the top 3 product categories was 0.2867 (28.67%), compared with a baseline of 0.2511 (25.11%) over 17-23 Nov 2017.",
          "kind": "measured",
          "observation_ids": ["obs-3"]
        },
        {
          "text": "The relative increase was about 0.1418 (14.18%), supporting a mix shift toward higher-frequency categories.",
          "kind": "inferred",
          "observation_ids": ["obs-3"]
        }
      ],
      "next_checks": ["Verify category-level order counts to confirm which categories drove the mix shift."]
    },
    {
      "hypothesis_id": "H4",
      "type": "single_seller",
      "summary": "A single seller generated a disproportionate number of orders on 24 Nov 2017.",
      "confidence": 0.6,
      "observation_ids": ["obs-4"],
      "statements": [
        {
          "text": "Seller 891071be6ba827b591264c90c2ae8a63 recorded 10 orders on 2017-11-24 against a baseline average of 0.1429 orders per day (17–23 November 2017), a 70.0x spike.",
          "kind": "measured",
          "observation_ids": ["obs-4"]
        }
      ],
      "next_checks": ["Assess whether this seller's orders account for a significant share of the total order count increase."]
    }
  ],
  "ruled_out": [
    {
      "hypothesis_id": "H1",
      "type": "data_artefact",
      "why": "There were 0 duplicate order IDs on 24 Nov 2017 and 0 duplicates in the baseline, so duplicate records did not cause the spike.",
      "observation_ids": ["obs-1"]
    },
    {
      "hypothesis_id": "H2",
      "type": "price_discount",
      "why": "The proportion of orders with a discount was 1.0 in both the 24 Nov window and the 17-23 Nov baseline, so a new promotional discount did not drive the spike.",
      "observation_ids": ["obs-2"]
    }
  ],
  "limitations": [
    "The data cannot confirm whether the mix shift fully explains the 1,176 vs 136.571 order-volume spike.",
    "Category-level order counts were not broken out, so the specific categories driving the mix shift are unidentified.",
    "The single seller's 10 orders represent a small fraction of the total order count increase, limiting its explanatory power for the overall spike."
  ],
  "follow_up": [
    {
      "id": "H5",
      "family": "mix_shift",
      "statement": "Specific high-frequency product categories drove the increased order volume on 24 Nov 2017.",
      "priority": 1,
      "test": {
        "description": "Measure order volume by product category on 24 Nov 2017 versus the 17-23 Nov baseline to identify which categories increased most.",
        "sources": ["orders"]
      }
    },
    {
      "id": "H6",
      "family": "volume",
      "statement": "Other sellers or logistics factors contributed to the remaining order volume increase beyond the single seller and mix shift.",
      "priority": 2,
      "test": {
        "description": "Analyze order counts per seller on 24 Nov 2017 and compare to baseline to identify additional contributors.",
        "sources": ["orders"]
      }
    }
  ]
